function drawXerneasRainbowStag(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.0;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const gems = ['#ef4444', '#f97316', '#fef08a', '#22c55e', '#06b6d4', '#3b82f6', '#a855f7', '#f472b6'];

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 44, 28 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Gạc sừng vàng & 8 ngọc cầu vồng
  ctx.strokeStyle = '#facc15'; ctx.lineWidth = 2.5;
  ctx.beginPath();
  // Nhánh trái
  ctx.moveTo(-2,  by - 16); ctx.lineTo(-18, by - 32); ctx.lineTo(-32, by - 44);
  ctx.moveTo(-18, by - 32); ctx.lineTo(-22, by - 46);
  ctx.moveTo(-10, by - 24); ctx.lineTo(-12, by - 42);
  // Nhánh phải
  ctx.moveTo(2,   by - 16); ctx.lineTo(18,  by - 32); ctx.lineTo(32,  by - 44);
  ctx.moveTo(18,  by - 32); ctx.lineTo(22,  by - 46);
  ctx.moveTo(10,  by - 24); ctx.lineTo(12,  by - 42);
  ctx.stroke();

  const gemCoords = [
    [-32, by - 44], [-22, by - 46], [-12, by - 42], [-4, by - 34],
    [4, by - 34],   [12, by - 42],  [22, by - 46],  [32, by - 44]
  ];
  gemCoords.forEach((pt, i) => {
    ctx.fillStyle = gems[i];
    ctx.beginPath(); ctx.arc(pt[0], pt[1], 3, 0, Math.PI * 2); ctx.fill();
  });

  // 3. Thân
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 16 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.moveTo(-8, by + 10); ctx.lineTo(0, by + 2); ctx.lineTo(8, by + 10); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-6, by + 6);  ctx.lineTo(0, by + 16); ctx.lineTo(6, by + 6);  ctx.fill();

  // 4. 4 Chân & Móng
  ctx.fillStyle = '#1e293b';
  [-12, -4, 4, 10].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 18, 4, 19, 2); ctx.fill();
  });
  ctx.fillStyle = '#facc15';
  [-12, -4, 4, 10].forEach(x => {
    ctx.fillRect(x, by + 36, 4, 3);
  });

  // 5. Cổ & Đầu
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.roundRect(-4, by - 6, 8, 16, 3); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0, by - 12, 8, 7, 0, 0, Math.PI * 2); ctx.fill();

  // 6. Mắt chữ thập
  if (!blink) {
    ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(-4, by - 12); ctx.lineTo(4, by - 12);
    ctx.moveTo(0,  by - 15); ctx.lineTo(0, by - 9);
    ctx.stroke();
  }

  ctx.restore();
}
